import pytest
import json
import os
from validator import SwaggerSchemaValidator

# Import fixtures from conftest.py
pytest_plugins = ["conftest"]  

# Load test data from JSON file
TEST_DATA_FILE = os.path.join(os.path.dirname(__file__), "astronomy.json.json")
with open(TEST_DATA_FILE, "r") as f:
    TEST_DATA = json.load(f)

# Path to the API OpenAPI Specification file
API_SPEC_FILE = os.path.join(os.path.dirname(__file__), "api.json")

# Initialize the SwaggerSchemaValidator
validator = SwaggerSchemaValidator(API_SPEC_FILE)

@pytest.mark.parametrize("test_case", TEST_DATA)
def test_astronomy_api(test_case, api_client, valid_api_key):
    """
    Test the /v1/astronomy.json endpoint for different scenarios described in astronomy.json.json.
    """
    endpoint = "/v1/astronomy.json"
    headers = {"Authorization": f"Bearer {valid_api_key}"}
    
    # Parameter extraction
    params = {
        "q": test_case.get("q", ""),
        "dt": test_case.get("dt", "")
    }
    
    # Send GET request
    response = api_client.get(endpoint, headers=headers, params=params) 
    
    # Validate response status code
    assert response.status_code == test_case["statusCode"], f"Unexpected status code: {response.status_code}"

    # Validate response body for successful cases
    if response.status_code == 200:
        response_json = response.json()
        assert validator.validate_with_schema(
            response_json,
            validator.get_schema("200")
        ), "Response schema validation failed for status code 200."
        
    # Validate error responses
    elif response.status_code in [400, 401, 403]:
        response_json = response.json()
        assert validator.validate_with_schema(
            response_json,
            validator.get_schema(str(response.status_code))
        ), f"Response schema validation failed for status code {response.status_code}."
        assert "message" in response_json, "Error message missing in response."

@pytest.mark.parametrize("security_test_case", ["valid", "invalid", "missing"])
def test_authentication_security(api_client, valid_api_key, invalid_api_key, security_test_case):
    """
    Test authentication security scenarios for /v1/astronomy.json endpoint.
    """
    endpoint = "/v1/astronomy.json"
    params = {"q": "London", "dt": "2023-10-10"}

    headers = {}
    if security_test_case == "valid":
        headers = {"Authorization": f"Bearer {valid_api_key}"}
    elif security_test_case == "invalid":
        headers = {"Authorization": f"Bearer {invalid_api_key}"}
    elif security_test_case == "missing":
        headers = {}

    # Send GET request and validate responses
    response = api_client.get(endpoint, headers=headers, params=params)
    if security_test_case == "valid":
        assert response.status_code == 200, f"Unexpected status code for valid API key: {response.status_code}"
    else:
        assert response.status_code in [401, 403], f"Unexpected status code for security test case {security_test_case}: {response.status_code}"
        response_json = response.json()
        assert "message" in response_json, f"Error message missing in response for test case {security_test_case}."

def test_invalid_parameters(api_client, valid_api_key):
    """
    Test invalid parameter scenarios for /v1/astronomy.json endpoint.
    """
    endpoint = "/v1/astronomy.json"
    headers = {"Authorization": f"Bearer {valid_api_key}"}
    invalid_params = [
        {"q": "", "dt": "2023-10-10"},  # Missing required query param "q"
        {"q": "London", "dt": ""},      # Missing required query param "dt"
        {"q": "INVALID_LOCATION", "dt": "2023-10-10"}  # Invalid location "q"
    ]

    for params in invalid_params:
        response = api_client.get(endpoint, headers=headers, params=params)
        assert response.status_code == 400, f"Unexpected status code: {response.status_code}"
        response_json = response.json()
        assert validator.validate_with_schema(
            response_json,
            validator.get_schema("400")
        ), "Response schema validation failed for status code 400."
        assert "message" in response_json, "Error message missing in response."

@pytest.mark.parametrize("boundary_case", [
    {"q": "a" * 255, "dt": "2023-10-10"},  # Max length for query param "q"
    {"q": "London", "dt": "2015-01-01"}    # Min date boundary for "dt"
])
def test_boundary_conditions(api_client, valid_api_key, boundary_case):
    """
    Test boundary conditions for /v1/astronomy.json endpoint.
    """
    endpoint = "/v1/astronomy.json"
    headers = {"Authorization": f"Bearer {valid_api_key}"}

    response = api_client.get(endpoint, headers=headers, params=boundary_case)
    assert response.status_code == 200, f"Unexpected status code for boundary case {boundary_case}: {response.status_code}"
    response_json = response.json()
    assert validator.validate_with_schema(
        response_json,
        validator.get_schema("200")
    ), "Response schema validation failed for boundary conditions."

